from fastapi.routing import APIRoute
from typing import Callable

response_cache = {}

class CachedJsonRoute(APIRoute):
    def get_route_handler(self) -> Callable:
        original_route_handler = super().get_route_handler()
        async def custom_handler(request: Request) -> Response:
            cache_key = request.url.path
            # Returns cached response before resolving dependencies (such as customer ownership checks)
            if request.method == "GET" and cache_key in response_cache:
                return Response(
                    content=response_cache[cache_key],
                    media_type="application/json",
                    headers={"X-Cache-Hit": "1"}
                )
            response: Response = await original_route_handler(request)
            if response.status_code == 200:
                response_cache[cache_key] = response.body
            return response
        return custom_handler

